func TestInitiateConversionDirectBranchConvertsAndCreatesCustomer(t *testing.T) {
	department := "dept-east"
	amount := schema.LeadExpectedAmount("99999.99")
	leadCapability := &initiateConversionLeadStub{
		record:       schema.Lead{ID: "lead-1", UpdatedAt: "rev-1", CompanyName: "Acme", ExpectedAmount: &amount, OwnerDepartmentID: &department, OwnerID: "rep-1", Status: schema.LeadStatusQualified},
		updateResult: schema.Lead{ID: "lead-1", UpdatedAt: "rev-2", Status: schema.LeadStatusConverted},
	}
	approvals := &initiateConversionApprovalStub{}
	customers := &initiateConversionCustomerStub{}
	output, err := InitiateConversion(t.Context(), capabilities.InitiateConversionCapabilities{
		Execution:          initiateConversionExecutionStub{principal: capabilities.Principal{Known: true, UserID: "rep-1", RoleKey: "sales_rep", DepartmentID: department}, targetID: "lead-1"},
		ConversionApproval: approvals,
		Customer:           customers,
		Lead:               leadCapability,
	}, capabilities.InitiateConversionInput{RequestID: "request-1"})
	if err != nil {
		t.Fatalf("InitiateConversion returned error: %v", err)
	}
	if output.Branch != schema.LeadInitiateConversionBranchDirect || output.CustomerID == nil || *output.CustomerID != "customer-1" || output.ApprovalID != nil {
		t.Fatalf("unexpected output: %+v", output)
