	if leadCapability.updateCalls != 1 || customers.createCalls != 1 || approvals.createCalls != 0 {
		t.Fatalf("unexpected effects: lead=%d customer=%d approval=%d", leadCapability.updateCalls, customers.createCalls, approvals.createCalls)
	}
	if customers.created.ExpectedAmount != "99999.99" || customers.created.SourceLeadID.ID() != "lead-1" {
		t.Fatalf("customer facts not preserved: %+v", customers.created)
	}
}

