		t.Fatalf("all-existing run called a zero mutation batch or returned wrong counts: output=%+v exists=%d create=%d dispatch=%d", output, receipts.existsBatchCalls, receipts.createBatchCalls, notifications.dispatchBatchCalls)
	}
}

func TestDispatchStaleRemindersFailsClosedOnBatchFailures(t *testing.T) {
	scheduledAt := time.Date(2026, 8, 19, 9, 0, 0, 0, time.UTC)
	staleAt := scheduledAt.Add(-8 * 24 * time.Hour)
	leadCapability := func() *dispatchStaleRemindersLeadStub {
		return &dispatchStaleRemindersLeadStub{records: []schema.Lead{{ID: "lead-1", UpdatedAt: "rev-1", CompanyName: "Acme", OwnerID: "rep-1", Status: schema.LeadStatusContacted, StatusChangedAt: &staleAt}}}
	}
	batchError := errors.New("batch failed")
	tests := []struct {
		name              string
		receipts          *dispatchStaleRemindersReceiptStub
		notifications     *dispatchStaleRemindersNotificationStub
		expectedError     error
		expectedErrorCode string
	}{
		{name: "exists error", receipts: &dispatchStaleRemindersReceiptStub{existsError: batchError}, notifications: &dispatchStaleRemindersNotificationStub{}, expectedError: batchError},
		{name: "exists cardinality", receipts: &dispatchStaleRemindersReceiptStub{existsResults: nil}, notifications: &dispatchStaleRemindersNotificationStub{}, expectedErrorCode: "lead.dispatch_stale_reminders.capability_result_invalid"},
		{name: "create error", receipts: &dispatchStaleRemindersReceiptStub{existsResults: []bool{false}, createError: batchError}, notifications: &dispatchStaleRemindersNotificationStub{}, expectedError: batchError},
		{name: "create cardinality", receipts: &dispatchStaleRemindersReceiptStub{existsResults: []bool{false}, createResults: nil}, notifications: &dispatchStaleRemindersNotificationStub{}, expectedErrorCode: "lead.dispatch_stale_reminders.mutation_invalid"},
		{name: "create empty identity", receipts: &dispatchStaleRemindersReceiptStub{existsResults: []bool{false}, createResults: []schema.LeadReminderReceipt{{}}}, notifications: &dispatchStaleRemindersNotificationStub{}, expectedErrorCode: "lead.dispatch_stale_reminders.mutation_invalid"},
		{name: "dispatch error", receipts: &dispatchStaleRemindersReceiptStub{existsResults: []bool{false}, createResults: []schema.LeadReminderReceipt{{ID: "receipt-1"}}}, notifications: &dispatchStaleRemindersNotificationStub{dispatchError: batchError}, expectedError: batchError},
		{name: "dispatch cardinality", receipts: &dispatchStaleRemindersReceiptStub{existsResults: []bool{false}, createResults: []schema.LeadReminderReceipt{{ID: "receipt-1"}}}, notifications: &dispatchStaleRemindersNotificationStub{}, expectedErrorCode: "lead.dispatch_stale_reminders.notification_invalid"},
		{name: "dispatch empty identity", receipts: &dispatchStaleRemindersReceiptStub{existsResults: []bool{false}, createResults: []schema.LeadReminderReceipt{{ID: "receipt-1"}}}, notifications: &dispatchStaleRemindersNotificationStub{results: []string{""}}, expectedErrorCode: "lead.dispatch_stale_reminders.notification_invalid"},
	}

	for _, testCase := range tests {
		t.Run(testCase.name, func(t *testing.T) {
			_, err := DispatchStaleReminders(t.Context(), capabilities.DispatchStaleRemindersCapabilities{
				Execution:           dispatchStaleRemindersExecutionStub{principal: capabilities.Principal{Known: true, RoleKey: "crm_scheduler"}},
				Lead:                leadCapability(),
				LeadReminderReceipt: testCase.receipts,
				Notifications:       testCase.notifications,
			}, capabilities.DispatchStaleRemindersInput{ScheduledAt: scheduledAt})
			if testCase.expectedError != nil {
				if !errors.Is(err, testCase.expectedError) {
					t.Fatalf("expected %v, got %v", testCase.expectedError, err)
				}
			} else {
				assertDispatchStaleRemindersErrorCode(t, err, testCase.expectedErrorCode)
			}
			if testCase.receipts.existsBatchCalls != 1 {
				t.Fatalf("ExistsBatch calls = %d, want 1", testCase.receipts.existsBatchCalls)
			}
			if testCase.receipts.createBatchCalls > 1 || testCase.notifications.dispatchBatchCalls > 1 {
				t.Fatalf("batch called more than once: create=%d dispatch=%d", testCase.receipts.createBatchCalls, testCase.notifications.dispatchBatchCalls)
			}
		})
	}
}

func TestDispatchStaleRemindersRejectsWeekendBeforeQuery(t *testing.T) {
	leads := &dispatchStaleRemindersLeadStub{}
	_, err := DispatchStaleReminders(t.Context(), capabilities.DispatchStaleRemindersCapabilities{}, capabilities.DispatchStaleRemindersInput{ScheduledAt: time.Date(2026, 8, 22, 9, 0, 0, 0, time.UTC)})
	assertDispatchStaleRemindersErrorCode(t, err, "lead.dispatch_stale_reminders.invalid_schedule")
	if leads.listCalls != 0 {
		t.Fatal("weekend schedule queried leads")
	}
}

func TestDispatchStaleRemindersRejectsMalformedCandidateWithoutEffects(t *testing.T) {
	scheduledAt := time.Date(2026, 8, 19, 9, 0, 0, 0, time.UTC)
	staleAt := scheduledAt.Add(-8 * 24 * time.Hour)
	receipts := &dispatchStaleRemindersReceiptStub{}
	notifications := &dispatchStaleRemindersNotificationStub{}
	_, err := DispatchStaleReminders(t.Context(), capabilities.DispatchStaleRemindersCapabilities{
		Execution:           dispatchStaleRemindersExecutionStub{principal: capabilities.Principal{Known: true, RoleKey: "crm_scheduler"}},
		Lead:                &dispatchStaleRemindersLeadStub{records: []schema.Lead{{ID: "lead-1", UpdatedAt: "rev-1", CompanyName: "Acme", OwnerID: "rep-1", Status: schema.LeadStatusQualified, StatusChangedAt: &staleAt}}},
		LeadReminderReceipt: receipts,
		Notifications:       notifications,
	}, capabilities.DispatchStaleRemindersInput{ScheduledAt: scheduledAt})
	assertDispatchStaleRemindersErrorCode(t, err, "lead.dispatch_stale_reminders.candidate_invalid")
	if receipts.existsBatchCalls != 0 || receipts.createBatchCalls != 0 || notifications.dispatchBatchCalls != 0 || len(receipts.created) != 0 || len(notifications.intents) != 0 {
		t.Fatal("invalid candidate produced effects")
	}
}

func assertDispatchStaleRemindersErrorCode(t *testing.T, err error, expected string) {
	t.Helper()
	var businessError *capabilities.BusinessError
	if !errors.As(err, &businessError) || businessError.Code != expected {
		t.Fatalf("expected %s, got %T %v", expected, err, err)
	}
}

